ALTER TABLE "Mission" ADD COLUMN "charterId" TEXT, ADD COLUMN "charterVersion" INTEGER, ADD COLUMN "economicStatus" TEXT NOT NULL DEFAULT 'untracked', ADD COLUMN "measurementEndsAt" TIMESTAMP(3), ADD COLUMN "measurementStartedAt" TIMESTAMP(3), ADD COLUMN "missionTemplateId" TEXT, ADD COLUMN "pricingModel" TEXT, ADD COLUMN "revenueStreamId" TEXT, ADD COLUMN "revenueTargetMinor" BIGINT;
CREATE TABLE "FoundryCharter" ("id" TEXT NOT NULL,"version" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'draft',"name" TEXT NOT NULL,"goal" TEXT NOT NULL,"constraints" TEXT[],"allowedToolClasses" TEXT[],"requiredApprovalRules" TEXT[],"maxMissionBudgetMinor" BIGINT NOT NULL,"monthlyOperatingBudgetMinor" BIGINT NOT NULL,"monthlyExperimentBudgetMinor" BIGINT NOT NULL,"currency" TEXT NOT NULL,"defaultTokenBudget" INTEGER NOT NULL,"hardTokenCeiling" INTEGER NOT NULL,"maxParallelMissions" INTEGER NOT NULL,"reviewIntervalDays" INTEGER NOT NULL,"approvedBy" TEXT,"approvedAt" TIMESTAMP(3),"supersedesId" TEXT,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "FoundryCharter_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MissionTemplate" ("id" TEXT NOT NULL,"key" TEXT NOT NULL,"version" INTEGER NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"missionType" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'draft',"defaultRiskLevel" TEXT NOT NULL,"defaultBudgetMinor" BIGINT NOT NULL,"defaultTokenBudget" INTEGER NOT NULL,"defaultMaxParallelTasks" INTEGER NOT NULL,"allowedToolClasses" TEXT[],"requiredApprovalRules" TEXT[],"definitionOfDoneTemplate" TEXT[],"failureConditionsTemplate" TEXT[],"measurementWindowDays" INTEGER NOT NULL,"leadingIndicators" TEXT[],"laggingIndicators" TEXT[],"killCriteria" TEXT[],"pricingModels" TEXT[],"createdBy" TEXT NOT NULL,"certifiedBy" TEXT,"certifiedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MissionTemplate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RevenueStream" ("id" TEXT NOT NULL,"projectId" TEXT,"businessId" TEXT,"name" TEXT NOT NULL,"key" TEXT NOT NULL,"missionType" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'proposed',"pricingModel" TEXT NOT NULL,"owner" TEXT NOT NULL,"currency" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RevenueStream_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EconomicEvent" ("id" TEXT NOT NULL,"missionId" TEXT,"projectId" TEXT,"revenueStreamId" TEXT,"type" TEXT NOT NULL,"amountMinor" BIGINT NOT NULL,"currency" TEXT NOT NULL,"category" TEXT NOT NULL,"source" TEXT NOT NULL,"externalReference" TEXT,"attributionMethod" TEXT NOT NULL,"evidence" JSONB,"idempotencyKey" TEXT NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL,"recordedBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EconomicEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "FoundryCharter_version_key" ON "FoundryCharter"("version"); CREATE UNIQUE INDEX "FoundryCharter_supersedesId_key" ON "FoundryCharter"("supersedesId"); CREATE INDEX "FoundryCharter_status_idx" ON "FoundryCharter"("status");
CREATE UNIQUE INDEX "FoundryCharter_single_active_key" ON "FoundryCharter" ((status)) WHERE status = 'active';
CREATE UNIQUE INDEX "MissionTemplate_key_version_key" ON "MissionTemplate"("key","version"); CREATE INDEX "MissionTemplate_status_missionType_idx" ON "MissionTemplate"("status","missionType");
CREATE UNIQUE INDEX "RevenueStream_key_key" ON "RevenueStream"("key"); CREATE INDEX "RevenueStream_projectId_status_idx" ON "RevenueStream"("projectId","status"); CREATE INDEX "RevenueStream_businessId_status_idx" ON "RevenueStream"("businessId","status");
CREATE UNIQUE INDEX "EconomicEvent_idempotencyKey_key" ON "EconomicEvent"("idempotencyKey"); CREATE INDEX "EconomicEvent_missionId_occurredAt_idx" ON "EconomicEvent"("missionId","occurredAt"); CREATE INDEX "EconomicEvent_projectId_occurredAt_idx" ON "EconomicEvent"("projectId","occurredAt"); CREATE INDEX "EconomicEvent_revenueStreamId_occurredAt_idx" ON "EconomicEvent"("revenueStreamId","occurredAt"); CREATE INDEX "EconomicEvent_type_occurredAt_idx" ON "EconomicEvent"("type","occurredAt");
CREATE INDEX "Mission_charterId_charterVersion_idx" ON "Mission"("charterId","charterVersion"); CREATE INDEX "Mission_missionTemplateId_idx" ON "Mission"("missionTemplateId"); CREATE INDEX "Mission_revenueStreamId_economicStatus_idx" ON "Mission"("revenueStreamId","economicStatus");
ALTER TABLE "Mission" ADD CONSTRAINT "Mission_charterId_fkey" FOREIGN KEY ("charterId") REFERENCES "FoundryCharter"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
